tement":"gamma in [0.5, 2], a benchmark subset of the theorem gamma > 0.","maximum":2.0,"minimum":0.5,"name":"gamma","unit":"dimensionless"}],"fixed_conditions":[{"anchors":[{"line_end":333,"line_start":333,"support":"The text states 'one can reproduce the defect SRE with r1=r2=1/2 precisely'."}],"condition_id":"r1_r2_half","statement":"The R-symmetry background parameters are set to r1 = r2 = 1/2."},{"anchors":[{"line_end":100,"line_start":100,"support":"For 1/2-BPS Wilson surfaces in 6d A_(N-1) N=(2,0) SCFT, both T and S can be calculated holographically."}],"condition_id":"six_dimensional_2_0_theory","statement":"The theory is the 6d A_(N-1) (2,0) SCFT."},{"anchors":[{"line_end":100,"line_start":100,"support":"For 1/2-BPS Wilson surfaces in 6d A_(N-1) N=(2,0) SCFT..."}],"condition_id":"wilson_surface_half_bps","statement":"The defect is a 1/2-BPS Wilson surface."},{"anchors":[{"line_end":104,"line_start":104,"support":"The representation is in A_(N-1) Lie algebra su(N)."}],"condition_id":"N_equals_4","statement":"The A_(N-1) / su(N) parameter is fixed to N=4 (the A3 theory)."},{"anchors":[{"line_end":104,"line_start":104,"support":"The representation is in A_(N-1) Lie algebra su(N)."}],"condition_id":"k_equals_2","statement":"The representation label is fixed to k = 2."},{"anchors":[{"line_end":110,"line_start":104,"support":"For the symmetric representation (k), eq-b-d2-Sk gives b_(k) and d2_(k)."}],"condition_id":"symmetric_representation","statement":"The defect is in the symmetric representation (k) of A_(N-1)."},{"anchors":[{"line_end":117,"line_start":111,"support":"For the antisymmetric representation [k], eq-b-d2-Ak gives b_[k] and d2_[k]."}],"condition_id":"antisymmetric_representation","statement":"The defect is in the antisymmetric representation [k] of A_(N-1)."}],"mechanisms":[{"anchors":[{"line_end":144,"line_start":140,"support":"The main result is stated: S_gamma = (2b - d2)/6 [r1 r2/2 (gamma - 1) + 1] log(ell/epsilon), with b and d2 given by eq-b-d2-R and r1+r2=1."}],"equations":["S_gamma = (2b - d2)/6 * [r1 r2/2 (gamma - 1) + 1] log(ell/epsilon)"],"mechanism_id":"defect_sre_formula","parameters":[{"anchors":[{"line_end":142,"line_start":142,"support":"The formula contains the constant 1 in the bracket [r1 r2/2 (gamma - 1) + 1]."}],"name":"one","role":"the constant 1 appearing in the bracket and in (N-1)","uncertainty":"source_unspecified","unit":"dimensionless","value":1.0},{"anchors":[{"line_end":333,"line_start":333,"support":"The text states 'plugging in sigma1=sigma2=(3+1/n)/2, omega1=1/n and omega_{2,3,4}=1, one can reproduce the defect SRE with r1=r2=1/2 precisely'."}],"name":"gamma_coefficient","role":"coefficient of (gamma - 1) in the bracket, with r1=r2=1/2","uncertainty":"source_unspecified","unit":"dimensionless","value":0.125},{"anchors":[{"line_end":108,"line_start":107,"support":"For the symmetric representation (k), b_(k) = 12 N k + 3 k^2 - 12 k - 3 k^2/N and d2_(k) = 12 N k + 6 k^2 - 12 k - 6 k^2/N."},{"line_end":142,"line_start":142,"support":"The main result S_gamma = (2b - d2)/6 [r1 r2/2 (gamma - 1) + 1] log(ell/epsilon) is stated."}],"name":"branch_amplitude_symmetric","role":"amplitude (2b - d2)/6 for the symmetric representation (k) with N=4, k=2","uncertainty":"source_unspecified","unit":"dimensionless","value":12.0},{"anchors":[{"line_end":115,"line_start":114,"support":"For the antisymmetric representation [k], b_[k] = 12 N k - 12 k^2 + 3 k - 3 k^2/N and d2_[k] = 12 N k - 12 k^2 + 6 k - 6 k^2/N."},{"line_end":142,"line_start":142,"support":"The main result S_gamma = (2b - d2)/6 [r1 r2/2 (gamma - 1) + 1] log(ell/epsilon) is stated."}],"name":"branch_amplitude_antisymmetric","role":"amplitude (2b - d2)/6 for the antisymmetric representation [k] with N=4, k=2","uncertainty":"source_unspecified","unit":"dimensionless","value":8.0}],"statement":"The defect contribution to supersymmetric Rényi entropy for 1/2-BPS Wilson surfaces in 6d A_(N-1) (2,0) theories is a linear function of gamma=